        if (points_in_hull > 0 && x <= last_x)
            throw std::logic_error("Points must be increasing by x.");

        if (points_in_hull == 0) {
            first_x = x;
            first_y = y;
            min_slope = -std::numeric_limits<long double>::infinity();
            max_slope = std::numeric_limits<long double>::infinity();
